D = range(1, 10)
good_2_digit_numbers = set()

for a in D:
    for b in D:
        if a == b:
            continue

        m = 10 * a + b
        is_good = False

        # Condition 1: Removing b results in a. Check if a divides m.
        # Since a divides 10a, we need a | b.
        if b % a == 0:
            is_good = True

        # Condition 2: Removing a results in b. Check if b divides m.
        # Since b divides b, we need b | 10a.
        if m % b == 0:
            is_good = True

        if is_good:
            good_2_digit_numbers.add(m)

sorted_good_numbers = sorted(list(good_2_digit_numbers))
print(f"Good 2-digit numbers: {sorted_good_numbers}")
